 func (a *App) ensureTick() tea.Cmd {
-	d, ok := cadence(a.jobs.Running() > 0, a.wantsBlink(), a.motionStatic)
+	d, ok := a.wantedCadence()
 	if !ok || (a.anim.ticking && a.anim.interval <= d) {
